#include "../../src/machines/marble/marble_hud.cpp"
#endif
#include "marble_hud_fixture.h"

void setUp(void) {}
void tearDown(void) {}

#ifdef HAVE_ROM
static uint32_t crc32(const void *data, size_t n, uint32_t crc = 0) {
  const uint8_t *p = (const uint8_t *)data;
  crc = ~crc;
  while (n--) {
    crc ^= *p++;
    for (int k = 0; k < 8; k++) crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1)));
  }
  return ~crc;
}

// glyph rows (2 bpp, left pixel in bits 15-14) and the alpha code -> glyph map
static void test_glyphs(void) {
  TEST_ASSERT_EQUAL_UINT32(MARBLE_HUD_FIX_GLYPHS, sizeof(marble_hud_glyphs) / sizeof(marble_hud_glyphs[0]));
  TEST_ASSERT_EQUAL_HEX32(MARBLE_HUD_FIX_GLYPH_CRC, crc32(marble_hud_glyphs, sizeof(marble_hud_glyphs)));
  TEST_ASSERT_EQUAL_HEX32(MARBLE_HUD_FIX_MAP_CRC, crc32(marble_hud_glyph, sizeof(marble_hud_glyph)));
}

// 'S' (0x53) of SCORE: pens unpacked from the 2 bpp rows equal the model's font decode
static void test_glyph_pixels(void) {
  const uint8_t g = marble_hud_glyph['S'];
  TEST_ASSERT_NOT_EQUAL(MARBLE_HUD_NO_GLYPH, g);
  uint8_t pens[64];
  for (int y = 0; y < 8; y++) {
    for (int x = 0; x < 8; x++) {
      pens[y * 8 + x] = (marble_hud_glyphs[g][y] >> (14 - 2 * x)) & 3;
    }
  }
  TEST_ASSERT_EQUAL_HEX32(MARBLE_HUD_FIX_S_CRC, crc32(pens, sizeof(pens)));
}

// ROM palette, pulse table, bonus colours as RGB565
static void test_palette(void) {
  TEST_ASSERT_EQUAL_HEX32(MARBLE_HUD_FIX_PAL_CRC, crc32(marble_hud_pal, sizeof(marble_hud_pal)));
  TEST_ASSERT_EQUAL_HEX32(MARBLE_HUD_FIX_PULSE_CRC, crc32(marble_hud_pulse, sizeof(marble_hud_pulse)));
}

using marble_hud::Grid;
using marble_video::Hud;

static Hud hudOf(const MarbleHudCase &c) {
  Hud h = {};
  h.screen = c.screen;
  h.score = c.score;
  h.value = c.value;
  h.seconds = c.seconds;
  h.race = c.race;
  h.add = c.add;
  h.deaths = c.deaths;
  h.pal3 = c.pal3;
  h.pal11 = c.pal11;
  h.stage = c.stage;
  h.table = c.tcase;
  return h;
}

// title table of a layout case (marble_hud.py layout_table)
static marble_hiscore::Table tableOf(uint8_t tcase) {
  marble_hiscore::Table t = {};
  marble_hiscore::defaults(t);
  if (tcase) {
    memcpy(t.e[0].initials, "   ", 3);
    t.e[0].score = 9999999;
  }
  t.version = tcase;
  return t;
}

// grid rows as text on failure: printable codes, '#' opaque blank, '?' other glyphs
static void dump(const Grid &g) {
  for (int r = 0; r < marble_hud::ROWS; r++) {
    char line[marble_hud::COLS + 1];
    for (int c = 0; c < marble_hud::COLS; c++) {
      const uint16_t w = g.cells[r][c];
      const uint16_t code = w & 0x3ff;
      line[c] = code > 0x20 && code < 0x7f ? (char)code : code ? '?' : (w & 0x2000) ? '#' : '.';
    }
    line[marble_hud::COLS] = 0;
    printf("%02d %s\n", r, line);
  }
}

static Grid grid;  // 2 KB, not on the stack

// every layout case: cells and colours equal the model
static void test_layout(void) {
  const int n = sizeof(MARBLE_HUD_FIX_CASES) / sizeof(MARBLE_HUD_FIX_CASES[0]);
  for (int k = 0; k < n; k++) {
    const MarbleHudCase &c = MARBLE_HUD_FIX_CASES[k];
    marble_hud::build(grid, hudOf(c), tableOf(c.tcase));
    const uint32_t cells = crc32(grid.cells, sizeof(grid.cells));
    if (cells != c.grid_crc) {
      printf("case %d screen 0x%x\n", k, c.screen);
      dump(grid);
    }
    TEST_ASSERT_EQUAL_HEX32_MESSAGE(c.grid_crc, cells, "grid");
    TEST_ASSERT_EQUAL_HEX32_MESSAGE(c.pal_crc, crc32(grid.pal, sizeof(grid.pal)), "palette");
  }
}

// an unchanged state does not rebuild (prepare_frame calls build every frame)
static void test_no_rebuild(void) {
  const marble_hiscore::Table t = tableOf(0);
  const Hud h = hudOf(MARBLE_HUD_FIX_CASES[0]);
  marble_hud::build(grid, h, t);
  grid.cells[20][5] = 0x1234;
  marble_hud::build(grid, h, t);
  TEST_ASSERT_EQUAL_HEX16(0x1234, grid.cells[20][5]);

  Hud other = h;
  other.score++;
  marble_hud::build(grid, other, t);
  TEST_ASSERT_EQUAL_HEX16(0, grid.cells[20][5]);
}

// a table write (new version) rebuilds the title
static void test_title_rebuild(void) {
  marble_hiscore::Table t = tableOf(0);
  Hud h = {};
  h.screen = marble_hud::PAL | marble_hud::TITLE;
  h.stage = 2;
  h.table = t.version;
  marble_hud::build(grid, h, t);
  const uint32_t before = crc32(grid.cells, sizeof(grid.cells));
  t.e[0].score = 9999999;
  t.version++;
  h.table = t.version;
  marble_hud::build(grid, h, t);
  TEST_ASSERT_NOT_EQUAL(before, crc32(grid.cells, sizeof(grid.cells)));
}

// blend: opaque cell writes every pixel (pen 0 too), transparent cell only pens 1-3, rows
// without text and a palette off state leave the strip alone
static void test_blend(void) {
  const marble_hiscore::Table t = tableOf(0);
  Hud h = hudOf(MARBLE_HUD_FIX_CASES[0]);  // top items: '_' row 0 (colour 7), SCORE row 1
  marble_hud::build(grid, h, t);

  static uint16_t strip[marble_video::OUT_W * 8];
  const uint16_t BG = 0x5a5a;
  for (int row = 0; row < 2; row++) {
    for (uint16_t &p : strip) { p = BG; }
    marble_hud::blend(grid, row, strip);

    const uint16_t w = grid.cells[row][0];
    const uint8_t g = marble_hud_glyph[w & 0x3ff];
    const int base = ((w >> 10) & 7) * 4;
    for (int y = 0; y < 8; y++) {
      for (int x = 0; x < 8; x++) {
        const uint8_t pen = (marble_hud_glyphs[g][y] >> (14 - 2 * x)) & 3;
        const uint16_t want = pen || (w & 0x2000) ? grid.pal[base + pen] : BG;
        TEST_ASSERT_EQUAL_HEX16(want, strip[y * marble_video::OUT_W + x]);
      }
    }
  }

  for (uint16_t &p : strip) { p = BG; }
  marble_hud::blend(grid, 20, strip);  // no text
  for (uint16_t p : strip) { TEST_ASSERT_EQUAL_HEX16(BG, p); }

  h.screen = 0;  // palette off
  marble_hud::build(grid, h, t);
  marble_hud::blend(grid, 1, strip);
  for (uint16_t p : strip) { TEST_ASSERT_EQUAL_HEX16(BG, p); }
}
#endif

int main(int argc, char **argv) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  RUN_TEST(test_glyphs);
  RUN_TEST(test_glyph_pixels);
  RUN_TEST(test_palette);
  RUN_TEST(test_layout);
  RUN_TEST(test_no_rebuild);
  RUN_TEST(test_title_rebuild);
  RUN_TEST(test_blend);
#else
  printf("marble_rom.h missing: run romconv ./convert.sh marble\n");
#endif
  return UNITY_END();
}
